// Users.tsx

import React, { useState, useEffect, useRef } from "react";
import { useUsers } from "../hooks/useUsers";
import { fetchUsers } from "../api/userServices";
import { UserTable } from "../components/Table";

export interface User {
  id: string;
  first_name: string | null;
  last_name: string | null;
  image_url: string | null;
  about_me: string | null;
  professional_headline: string | null;
  location_allowed: boolean | null;
  certifications: string[];
  location_id: string[];
  user_type_id: string[];
  skills_id: string[];
  profile_attachments: string[];
  phone: string | null;
  created_at: string | null;
  updated_at: string | null;
  // Computed display helpers
  name: string;
  location: string;
  user_type_names: string[]; // resolved from user_types table e.g. ["client"] or ["bidder"]
}

type UserTypeFilter = "all" | "clients" | "bidders";
type StatusFilter   = "all" | "active" | "suspended" | "pending";

/* ── Column-visibility popover ───────────────────────────────── */
const ALL_EXTRA_COLUMNS = [
  { label: "Location", key: "location" as const },
  { label: "Phone",    key: "phone"    as const },
] satisfies { label: string; key: keyof User }[];

const ColVisPopover: React.FC<{
  visible: Set<string>;
  onChange: (key: string) => void;
  onClose: () => void;
}> = ({ visible, onChange, onClose }) => {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) onClose();
    };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, [onClose]);

  return (
    <div
      ref={ref}
      style={{
        position: "absolute", top: "calc(100% + 8px)", right: 0, zIndex: 50,
        background: "#fff", border: "1px solid #E2E8F0", borderRadius: 12,
        boxShadow: "0 8px 24px rgba(15,23,42,0.10)", padding: "8px 0", minWidth: 180,
      }}
    >
      <p style={{ margin: 0, padding: "6px 14px 10px", fontSize: 11, fontWeight: 600,
        color: "#94A3B8", textTransform: "uppercase", letterSpacing: 0.8 }}>
        Show / hide columns
      </p>
      {ALL_EXTRA_COLUMNS.map((col) => (
        <label
          key={col.key}
          style={{
            display: "flex", alignItems: "center", gap: 10,
            padding: "7px 14px", cursor: "pointer", fontSize: 14, color: "#334155",
          }}
        >
          <input
            type="checkbox"
            checked={visible.has(col.key)}
            onChange={() => onChange(col.key)}
            style={{ accentColor: "#EA580C", cursor: "pointer" }}
          />
          {col.label}
        </label>
      ))}
    </div>
  );
};

/* ── Dropdown ────────────────────────────────────────────────── */
const Dropdown: React.FC<{
  value: string;
  options: { label: string; value: string }[];
  onChange: (v: string) => void;
  placeholder: string;
}> = ({ value, options, onChange, placeholder }) => (
  <div style={{ position: "relative" }}>
    <select
      value={value}
      onChange={(e) => onChange(e.target.value)}
      style={{
        appearance: "none", WebkitAppearance: "none",
        padding: "9px 36px 9px 14px",
        border: "1px solid #E2E8F0", borderRadius: 10,
        background: "#fff", fontSize: 14, color: value === "all" ? "#94A3B8" : "#0F172A",
        cursor: "pointer", outline: "none", minWidth: 140,
        fontFamily: "inherit",
      }}
    >
      <option value="all">{placeholder}</option>
      {options.map((o) => (
        <option key={o.value} value={o.value}>{o.label}</option>
      ))}
    </select>
    {/* chevron */}
    <svg
      width="14" height="14" viewBox="0 0 14 14" fill="none"
      style={{ position: "absolute", right: 12, top: "50%", transform: "translateY(-50%)", pointerEvents: "none" }}
    >
      <path d="M3 5l4 4 4-4" stroke="#94A3B8" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  </div>
);

/* ── Main component ──────────────────────────────────────────── */
const Users: React.FC = () => {
  const [users, setUsers] = useState<User[]>([]);
  const [locationFilter, setLocationFilter] = useState<string>("all");
  const [statusFilter,   setStatusFilter]   = useState<StatusFilter>("all");
  const [userTypeFilter, setUserTypeFilter] = useState<UserTypeFilter>("all");
  const [visibleCols,    setVisibleCols]    = useState<Set<string>>(
    new Set(ALL_EXTRA_COLUMNS.map((c) => c.key))
  );
  const [showColPicker,  setShowColPicker]  = useState(false);

  const {
    searchTerm,
    setSearchTerm,
    filteredAndSortedUsers: baseFiltered,
    requestSort,
    sortConfig,
  } = useUsers(users);

  useEffect(() => {
    fetchUsers().then((data) => {
      const loaded = data as User[];
      // Debug: check what type names are actually resolved from Supabase
      if (loaded.length > 0) {
        console.log("[Users] sample user_type_id:", loaded[0].user_type_id);
        console.log("[Users] sample user_type_names:", loaded[0].user_type_names);
      }
      setUsers(loaded);
    });
  }, []);

  /* Apply local filters on top of the hook's search+sort */
  const filteredAndSortedUsers = baseFiltered.filter((u) => {
    if (locationFilter !== "all" && u.location !== locationFilter) return false;
    if (statusFilter !== "all") {
      const s = u.location_allowed === true  ? "active"
              : u.location_allowed === false ? "suspended"
              : "pending";
      if (s !== statusFilter) return false;
    }
    if (userTypeFilter !== "all") {
      // Guard: user_type_names may be missing on older cached objects
      const typeNames: string[] = (u.user_type_names ?? []).map((t) => t.toLowerCase());
      const wantType = userTypeFilter === "clients" ? "client" : "bidder";
      if (!typeNames.includes(wantType)) return false;
    }
    return true;
  });

  /* Unique locations for the dropdown */
  const locationOptions = Array.from(new Set(users.map((u) => u.location).filter(Boolean)))
    .map((l) => ({ label: l, value: l }));

  const toggleColVisibility = (key: string) => {
    setVisibleCols((prev) => {
      const next = new Set(prev);
      next.has(key) ? next.delete(key) : next.add(key);
      return next;
    });
  };

  const activeColumns = ALL_EXTRA_COLUMNS.filter((c) => visibleCols.has(c.key));

  const handleViewUser    = (user: User) => console.log("View user:", user);
  const handleSuspendUser = (user: User) => console.log("Toggle suspend:", user);

  return (
    <div style={{ width: "100%", display: "flex", flexDirection: "column", gap: 20,
      fontFamily: "'DM Sans', 'Helvetica Neue', sans-serif" }}>

      {/* ── TOOLBAR ─────────────────────────────────────────────── */}
      <div style={{
        display: "flex", alignItems: "center",
        justifyContent: "space-between", flexWrap: "wrap", gap: 12,
      }}>

        {/* LEFT — Search */}
        <div style={{ position: "relative", flexShrink: 0 }}>
          <svg width="16" height="16" viewBox="0 0 16 16" fill="none"
            style={{ position: "absolute", left: 12, top: "50%", transform: "translateY(-50%)", pointerEvents: "none" }}>
            <circle cx="7" cy="7" r="5.5" stroke="#94A3B8" strokeWidth="1.5" />
            <path d="M11 11l2.5 2.5" stroke="#94A3B8" strokeWidth="1.5" strokeLinecap="round" />
          </svg>
          <input
            type="text"
            placeholder="Search"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            style={{
              padding: "9px 14px 9px 36px",
              borderRadius: 10,
              border: "1px solid #E2E8F0",
              width: 240, maxWidth: "100%",
              outline: "none", fontSize: 14,
              color: "#0F172A", fontFamily: "inherit",
              background: "#fff",
            }}
          />
        </div>

        {/* RIGHT — filters + toggles + col picker */}
        <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>

          {/* Location dropdown */}
          <Dropdown
            value={locationFilter}
            options={locationOptions}
            onChange={setLocationFilter}
            placeholder="Location"
          />

          {/* Status dropdown */}
          <Dropdown
            value={statusFilter}
            options={[
              { label: "Active",    value: "active" },
              { label: "Suspended", value: "suspended" },
              { label: "Pending",   value: "pending" },
            ]}
            onChange={(v) => setStatusFilter(v as StatusFilter)}
            placeholder="Status"
          />

          {/* Clients / Bidders toggle */}
          <div style={{
            display: "flex", borderRadius: 10,
            border: "1px solid #E2E8F0", overflow: "hidden", background: "#fff",
          }}>
            {(["all", "clients", "bidders"] as const)
              .filter((t) => t !== "all")
              .map((type) => {
                const active = userTypeFilter === type;
                return (
                  <button
                    key={type}
                    onClick={() => setUserTypeFilter(active ? "all" : type)}
                    style={{
                      padding: "9px 18px", border: "none", cursor: "pointer",
                      background: active ? "#0F172A" : "#fff",
                      color: active ? "#fff" : "#64748B",
                      fontWeight: 600, fontSize: 14,
                      fontFamily: "inherit",
                      transition: "background 0.15s, color 0.15s",
                    }}
                  >
                    {type.charAt(0).toUpperCase() + type.slice(1)}
                  </button>
                );
              })}
          </div>

          {/* Column visibility */}
          <div style={{ position: "relative" }}>
            <button
              onClick={() => setShowColPicker((v) => !v)}
              title="Show / hide columns"
              style={{
                width: 40, height: 40,
                border: "1px solid #E2E8F0", borderRadius: 10,
                background: showColPicker ? "#F8FAFC" : "#fff",
                cursor: "pointer", display: "flex",
                alignItems: "center", justifyContent: "center",
                transition: "background 0.15s",
              }}
            >
              {/* grid / columns icon */}
              <svg width="18" height="18" viewBox="0 0 18 18" fill="none">
                <rect x="2" y="2" width="4" height="14" rx="1.5" stroke="#64748B" strokeWidth="1.5" />
                <rect x="8" y="2" width="4" height="14" rx="1.5" stroke="#64748B" strokeWidth="1.5" />
                <rect x="14" y="2" width="2" height="14" rx="1" stroke="#64748B" strokeWidth="1.5" />
              </svg>
            </button>

            {showColPicker && (
              <ColVisPopover
                visible={visibleCols}
                onChange={toggleColVisibility}
                onClose={() => setShowColPicker(false)}
              />
            )}
          </div>
        </div>
      </div>

      {/* ── TABLE ───────────────────────────────────────────────── */}
      <UserTable
        data={filteredAndSortedUsers}
        onSort={requestSort}
        sortConfig={sortConfig}
        onViewUser={handleViewUser}
        onSuspendUser={handleSuspendUser}
        rowsPerPage={10}
        columns={activeColumns}
      />
    </div>
  );
};

export default Users;
